/*
 * dir_$old_create_obj - create and initialise the object behind a new
 * old-format directory
 *
 * Original address: 0x00E54546
 * Size: 488 bytes (0x00E54546 .. 0x00E5472D)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the OLD_DIR segment (no map symbol); its one
 * caller is DIR_$OLD_CREATE_DIRU (0x00E5725A), which holds the PARENT
 * directory locked and mapped (handle).
 *
 * Frame: (0x8,A6) parent_uid, (0xC,A6) handle (D5, the parent's mapped
 * directory), (0x10,A6) type word, (0x12,A6) new_dir_uid (A3), (0x16,A6)
 * status_ret (A4).  D3b = created, D2b = locked, D4b = mapped (Domain
 * booleans, all FALSE at entry).  Locals: A6-0x8 the lock slot, A6-0x1E
 * the rights word, A6-0x18 MST_$MAPS' map info, A6-0x14 the DTV / flush
 * time, A6-0xC a private status, A6-0x20 AST_$TRUNCATE's boolean, A6-0x30
 * a default ACL UID.
 *
 * Blocks:
 *   0x00E54560-0x00E54584  FILE_$PRIV_CREATE(type, &UID_$NIL, parent_uid,
 *                          new_dir_uid, 0, 0, 0, status_ret); error -> 0x00E54608
 *   0x00E54588-0x00E545C4  created; FILE_$PRIV_LOCK(new_dir_uid,
 *                          PROC1_$AS_ID, 0, 4, locked (FALSE), 0x88, 0, 0,
 *                          0, 0, &NAME_$CONST_ZERO_L, 1, &slot, &rights,
 *                          status_ret)
 *   0x00E545C6-0x00E545F4  locked; A2 = MST_$MAPS(PROC1_$AS_ID, TRUE,
 *                          new_dir_uid, 0, 0x7FFF, 0x16, 0, TRUE, &info,
 *                          status_ret)
 *   0x00E545F6-0x00E54600  mapped; dir_$old_init_buf(A2); both info-block
 *                          lengths = 0x10
 *   0x00E54608-0x00E5462C  mapped: MST_$UNMAP_PRIVI(1, &UID_$NIL, A2,
 *                          0x7FFF, PROC1_$AS_ID, &private)
 *   0x00E54630-0x00E54658  locked: FILE_$PRIV_UNLOCK(new_dir_uid, slot, 4,
 *                          PROC1_$AS_ID, 0, 0, 0, 0, &dtv, &private)
 *   0x00E5465C-0x00E546E4  status ok: default ACLs.  A parent with fewer
 *                          than 0x13 inline slots and an info block of at
 *                          least 0x10 bytes passes its own on
 *                          (DIR_$OLD_SET_DEFAULT_ACL(new, &ACL_$FILE_ACL,
 *                          parent+0x38A), then &ACL_$DIR_ACL, parent+0x382);
 *                          otherwise ACL_$DEFAULT_ACL(&acl, &0) for files
 *                          and ACL_$DEFAULT_ACL(&acl, &type) for
 *                          directories, all with the private status
 *   0x00E546E8-0x00E546FC  AST_$COND_FLUSH(new_dir_uid, &0, &private);
 *                          status ok -> return
 *   0x00E54704-0x00E54720  failure: created -> AST_$TRUNCATE(new_dir_uid,
 *                          0, 3, &b, &private); then set bit 31 of
 *                          *status_ret (`bset.b #0x7,(A4)')
 *
 * Quirks reproduced:
 *   - FILE_$PRIV_LOCK's local_only byte is D2b, still FALSE at that point;
 *     MST_$MAPS' two booleans are D2b after `move.b D3b,D2b', i.e. TRUE.
 *   - ACL_$DEFAULT_ACL is called with two arguments; the private status
 *     pushed just before it is left on the stack and becomes the fourth
 *     argument of the following DIR_$OLD_SET_DEFAULT_ACL (0x00E54698-
 *     0x00E546BC and again at 0x00E546C0-0x00E546E4).
 *   - The directory type (0x10,A6) is passed to ACL_$DEFAULT_ACL by
 *     address (`pea (0x10,A6)').
 *   - The ACL and flush steps report into the private status only; the
 *     failure path is reached through status_ret alone.
 */

#include "dir/dir_internal.h"

/* `pea (0x4).w' 0x00E545AC: side 0, lock mode 4 */
#define OLD_CREATE_LOCK_MODE    4
/* `move.l #0x880000,-(SP)' 0x00E545A4: flags 0x88, key 0 */
#define OLD_CREATE_LOCK_FLAGS   0x0088
/* `move.w #0x16,-(SP)' 0x00E545D2 and the 0x7FFF length */
#define OLD_CREATE_MAP_AREA     0x16
#define OLD_CREATE_MAP_LENGTH   0x7FFF
/* `cmpi.w #0x13,(0x4,A0)' 0x00E54664 / `cmpi.w #0x10,(0x37e,A0)' 0x00E5466C */
#define OLD_CREATE_INHERIT_MAX_SLOTS  0x13
#define OLD_CREATE_INHERIT_INFO_LEN   0x10
/* `move.w #0x3,-(SP)' 0x00E54712: AST_$TRUNCATE flags */
#define OLD_CREATE_TRUNC_FLAGS  3

void dir_$old_create_obj(uid_t *parent_uid, uint32_t handle, int16_t type,
                         uid_t *new_dir_uid, status_$t *status_ret)
{
    uint8_t *parent = (uint8_t *)ARCH_VA_TO_PTR(handle);   /* D5 */
    uint8_t *dir = NULL;                                    /* A2 */
    int8_t created = 0;                                     /* D3b */
    int8_t mapped;                                          /* D4b */
    int8_t locked;                                          /* D2b */
    uint32_t slot;                                          /* A6-0x8 */
    uint16_t rights;                                        /* A6-0x1E */
    uint8_t map_info[8];                                    /* A6-0x18 */
    uint32_t dtv;                                           /* A6-0x14 */
    status_$t status;                                       /* A6-0xC */
    boolean trunc_result;                                   /* A6-0x20 */
    uid_t acl;                                              /* A6-0x30 */

    mapped = created;
    locked = created;

    /* 0x00E54560-0x00E54584 */
    FILE_$PRIV_CREATE(type, &UID_$NIL, parent_uid, new_dir_uid, 0, 0, NULL,
                      status_ret);
    if (*status_ret == status_$ok) {
        /* 0x00E54588-0x00E545C4 */
        created = (int8_t)0xFF;
        FILE_$PRIV_LOCK(new_dir_uid, (int16_t)PROC1_$AS_ID, 0,
                        OLD_CREATE_LOCK_MODE, (boolean)locked,
                        OLD_CREATE_LOCK_FLAGS, 0, 0, 0, 0,
                        (void **)&NAME_$CONST_ZERO_L, 1, &slot, &rights,
                        status_ret);
        if (*status_ret == status_$ok) {
            /* 0x00E545C6-0x00E545F4 */
            locked = created;
            dir = (uint8_t *)MST_$MAPS((int16_t)PROC1_$AS_ID, (boolean)locked,
                                       new_dir_uid, 0, OLD_CREATE_MAP_LENGTH,
                                       OLD_CREATE_MAP_AREA, 0,
                                       (boolean)locked, map_info, status_ret);
            if (*status_ret == status_$ok) {
                /* 0x00E545F6-0x00E54600 */
                mapped = locked;
                dir_$old_init_buf(dir);
                DIR_OLD_W(dir, DIR_OLD_HDR_INFO_WRITE_LEN) = 0x0010;
                DIR_OLD_W(dir, DIR_OLD_HDR_INFO_READ_LEN) = 0x0010;
            }
        }
    }

    /* 0x00E54608-0x00E5462C */
    if (mapped < 0) {
        MST_$UNMAP_PRIVI(1, &UID_$NIL, ARCH_PTR_TO_VA(dir),
                         OLD_CREATE_MAP_LENGTH, PROC1_$AS_ID, &status);
    }

    /* 0x00E54630-0x00E54658 */
    if (locked < 0) {
        FILE_$PRIV_UNLOCK(new_dir_uid, (int32_t)slot, OLD_CREATE_LOCK_MODE,
                          PROC1_$AS_ID, 0, 0, 0, 0, &dtv, &status);
    }

    if (*status_ret == status_$ok) {
        /* 0x00E54662-0x00E546E4 */
        if (DIR_OLD_W(parent, DIR_OLD_HDR_INLINE_SLOTS) <
                OLD_CREATE_INHERIT_MAX_SLOTS &&
            (int16_t)DIR_OLD_W(parent, DIR_OLD_HDR_INFO_READ_LEN) >=
                OLD_CREATE_INHERIT_INFO_LEN) {
            DIR_$OLD_SET_DEFAULT_ACL(new_dir_uid, &ACL_$FILE_ACL,
                                     (uid_t *)(parent + DIR_OLD_INFO_FILE_ACL),
                                     &status);
            DIR_$OLD_SET_DEFAULT_ACL(new_dir_uid, &ACL_$DIR_ACL,
                                     (uid_t *)(parent + DIR_OLD_INFO_DIR_ACL),
                                     &status);
        } else {
            ACL_$DEFAULT_ACL(&acl, (int16_t *)&NAME_$CONST_ZERO_W);
            DIR_$OLD_SET_DEFAULT_ACL(new_dir_uid, &ACL_$FILE_ACL, &acl,
                                     &status);
            ACL_$DEFAULT_ACL(&acl, &type);
            DIR_$OLD_SET_DEFAULT_ACL(new_dir_uid, &ACL_$DIR_ACL, &acl,
                                     &status);
        }

        /* 0x00E546E8-0x00E546FC */
        dtv = 0;
        AST_$COND_FLUSH(new_dir_uid, &dtv, &status);
        if (*status_ret == status_$ok) {
            return;
        }
    }

    /* 0x00E54704-0x00E54720 */
    if (created < 0) {
        AST_$TRUNCATE(new_dir_uid, 0, OLD_CREATE_TRUNC_FLAGS, &trunc_result,
                      &status);
    }
    *status_ret |= (status_$t)0x80000000;
}
